import manifest from '../generated/media.json';

export interface StillEntry {
  poster: string;
  posterWebp: string;
  width: number;
  height: number;
}

export interface MediaEntry {
  kind: 'video' | 'image' | 'audio';
  width: number;
  height: number;
  aspect: string;
  duration?: number;
  hasAudio?: boolean;
  poster: string;
  posterWebp: string;
  loop?: string;
  full?: string;
  bytes?: Record<string, number>;
  stills?: StillEntry[];
}

const entries = manifest as Record<string, MediaEntry>;
const base = import.meta.env.BASE_URL;

/**
 * Look up a media item generated by `npm run media`.
 * "<video-id>@<n>" returns the n-th extracted still of that video as an image.
 */
export function media(id: string | undefined): MediaEntry | undefined {
  if (!id) return undefined;
  const [baseId, still] = id.split('@');
  if (still !== undefined) {
    const s = entries[baseId!]?.stills?.[Number(still)];
    if (!s && import.meta.env.DEV) console.warn(`[media] unknown still "${id}" — check "stills" in media.sources.json`);
    return s ? { kind: 'image', width: s.width, height: s.height, aspect: entries[baseId!]!.aspect, poster: s.poster, posterWebp: s.posterWebp } : undefined;
  }
  const entry = entries[id];
  if (!entry && import.meta.env.DEV) console.warn(`[media] unknown id "${id}" — run npm run media`);
  return entry;
}

export const url = (path: string | undefined) => (path ? `${typeof location!=='undefined'&&location.protocol==='file:'?'./':base}${path}` : undefined);

export const isPortrait = (m: MediaEntry | undefined) => !!m && m.height > m.width;

export function formatDuration(seconds: number | undefined): string {
  if (!seconds) return '';
  const s = Math.round(seconds);
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
}
